    "Script": "ResourceManagement = {
	init: async function (app, container) {
		app = app || session.app;
		container = container || $(".component[name=Resourcing]");
		api.addToMetaCache([
		{
        "Name": "Core",
        "Types": [
            [meta[Core/Resource]]
        ]
    }]);
		var config = {
			endpoint: "ContentManagement/Resource",
			odataAppend: "?$filter=AppId eq " + app.Id + " and Culture eq ''",
			group: { field: "Key" }
		};
		let cultures = await api.get("ContentManagement/Culture");
		let resourceDataSource = await model.getDatasource(config);
		let typeInfo = await api.getType("ContentManagement/Resource");
		await ResourceManagement.setupGrid(app,container,resourceDataSource, cultures, typeInfo);
	},

	setupGrid: async function(app,container, resourceDataSource, cultures, typeInfo) {
		var grid = new GridWidget(container, resourceDataSource);
		grid.toolbar = [
			{template: `
			<button name='create'><span class='k-icon k-i-plus'></span>[resource_displayname[newresource]]</button>
			<button name='migrate'>[resource_displayname[migrate]]</button>
		`}];
		grid.filterable = true;
		grid.searchable = true;
		grid.search = { fields: ["Key", "Name", "DisplayName", "ShortDisplayName", "Description", "LastUpdatedBy"] }; 
		grid.columns = [
			{ field: "Key", editable: false, title: "[resource_shortdisplayname[key]]", width: 80 },
			{ field: "Name", editable: false, title: "[resource_shortdisplayname[name]]", width: 200 },
			{ field: "DisplayName", title: "[resource_shortdisplayname[displayname]]", template: "#=(DisplayName && DisplayName.length > 80) ? ResourceManagement.escapeHtml(DisplayName.substring(0, 80)) + '...' : ResourceManagement.escapeHtml(DisplayName)#", encoded: true },
			{ field: "ShortDisplayName", title: "[resource_shortdisplayname[shortdisplayname]]", template: "#=(ShortDisplayName && ShortDisplayName.length > 80) ? ResourceManagement.escapeHtml(ShortDisplayName.substring(0, 80)) + '...' : ResourceManagement.escapeHtml(ShortDisplayName)#", encoded: true },
			{ field: "Description", title: "[resource_shortdisplayname[description]]", template: "#=(Description && Description.length > 80) ? ResourceManagement.escapeHtml(Description.substring(0, 80)) + '...' : ResourceManagement.escapeHtml(Description)#", encoded: true },
			{ field: "LastUpdated", title: "[resource_displayname[lastupdated]]", width: 120, type: "date", format: "{0: " + type.dateFormat + " hh:mm}" },
			{ field: "LastUpdatedBy", title: "[resource_displayname[lastupdated]]", width: 200 },
		];
		grid.commands.push({name: "save", icon: "k-i-save", text: "[resource_displayname[save]]"});
		grid.commands.push({name: "destroy", icon: "k-i-delete", text: "[resource_displayname[delete]]"});
		grid.detailTemplate =  "<div name='translations'></div>",
		grid.detailExpand = (e) => ResourceManagement.expandResource(e, app, grid, cultures.value, typeInfo);
		grid.dataBound = () => {
			$("a[name=save]", grid.gridElement).on("click", (e) => ResourceManagement.save(e, grid));
			$("a[name=destroy]", grid.gridElement).on("click", (e) => ResourceManagement.destroy(e, grid));
		};
		await grid.init();
		$("button[name=migrate]", grid.gridElement).on("click", (e) => ResourceManagement.migrate(app));
		$("button[name=create]", grid.gridElement).on("click", (e) => ResourceManagement.newResource(e, app, grid));
		$("input[name='searchResourcing']", grid.gridElement).off("keyup").keyup(ResourceManagement.delay((e) => ResourceManagement.search(e, grid, container, app, typeInfo), 500));
	},

	delay: function (callback, ms) {
		var timer = 0;
		return function () {
			var context = this, args = arguments;
			clearTimeout(timer);
			timer = setTimeout(function () {
				callback.apply(context, args);
			}, ms || 0);
		};
	},

	search: async function (grid, app, typeInfo) {
		var searchTerm = $("input[name='searchResourcing']", grid.gridElement).val();
		let data = await api.get("ContentManagement/Resource?$filter=AppId eq " + app.Id + " and Culture eq '' and (contains(Name, '" + searchTerm + "') or contains(DisplayName, '" + searchTerm + "') or contains(Description, '" + searchTerm + "') or contains(ShortDisplayName, '" + searchTerm + "') or contains(Key, '" + searchTerm + "'))");
		$.each(data.value, function (idx, item) {
			model.prepareItem(item, typeInfo);
		});
		grid.dataSource().data(data.value);
		grid.refresh();
	},

	expandResource: async function (e, app, grid, cultures, typeInfo) {
		var resource = grid.dataItem(e.masterRow);
		var container = $(e.detailRow);
		if($("[name=translationsGrid]", container).length === 0) {
			let translations = (await api.get("ContentManagement/Resource?$filter=AppId eq " + app.Id + " and Key eq '" + resource.Key + "' and Name eq '" + resource.Name + "' and Culture ne '' ")).value.map(r => {
				model.prepareItem(r, typeInfo);
				return r;
			});
			await ResourceManagement.setupTranslationsGrid(app, $("[name=translations]", container), resource, translations, cultures, typeInfo);
		}
	},

	escapeHtml: function(html) {
    	return html.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;').replaceAll('"', '&quot;').replaceAll("'", '&#039;');
	},

	setupTranslationsGrid: async function(app, container, resource, translations, cultures, typeInfo) {
		var translationsGrid = new GridWidget(container, translations);
		translationsGrid.groupable = false;
		translationsGrid.pageable = false;
		translationsGrid.filterable = false;
		translationsGrid.toolbar = kendo.template("<div><button name='createTranslation'><span class='k-icon k-i-plus'></span>[resource_displayname[newtranslation]]</button></div>");
		translationsGrid.columns = [
			{ field: "Culture", editable: false, title: "[resource_shortdisplayname[culture]]" },
			{ field: "Name", editable: false, title: "[resource_shortdisplayname[name]]" },
			{ field: "DisplayName", title: "[resource_shortdisplayname[displayname]]", template: "#=(DisplayName && DisplayName.length > 80) ? ResourceManagement.escapeHtml(DisplayName.substring(0, 80)) + '...' : ResourceManagement.escapeHtml(DisplayName)#", encoded: true },
			{ field: "ShortDisplayName", title: "[resource_shortdisplayname[shortdisplayname]]", template: "#=(ShortDisplayName && ShortDisplayName.length > 80) ? ResourceManagement.escapeHtml(ShortDisplayName.substring(0, 80)) + '...' : ResourceManagement.escapeHtml(ShortDisplayName)#", encoded: true },
			{ field: "Description", title: "[resource_shortdisplayname[description]]", template: "#=(Description && Description.length > 80) ? ResourceManagement.escapeHtml(Description.substring(0, 80)) + '...' : ResourceManagement.escapeHtml(Description)#", encoded: true },
			{ field: "LastUpdated", title: "[resource_displayname[lastupdated]]", width: 120, type: "date", format: "{0: " + type.dateFormat + " hh:mm}" },
			{ field: "LastUpdatedBy", title: "[resource_displayname[lastupdatedby]]", width: 200 },
		];
		translationsGrid.commands.push({ name: "save", icon: "k-i-save", text: "[resource_displayname[save]]" });
		translationsGrid.commands.push({name: "delete", icon: "k-i-delete", text: "[resource_displayname[delete]]" });
		translationsGrid.dataBound = function() {
			$("a[name=save]", translationsGrid.gridElement).on("click",  (e) => ResourceManagement.save(e, translationsGrid));
			$("[name=delete]", translationsGrid.gridElement).on("click", (e) => ResourceManagement.destroy(e, translationsGrid));
		};
		await translationsGrid.init();
		$("button[name=createTranslation]", translationsGrid.gridElement).on("click", (e) => ResourceManagement.createTranslation(e, app, resource, translationsGrid, cultures, typeInfo));
	},

	createTranslation: async function(e, app, resource, translationsGrid, cultures, typeInfo) {
		e.preventDefault();
		var options = cultures.filter((c) => c.Id !== '' && translationsGrid.dataSource().data().filter((r) => r.Culture === c.Id).length === 0);
		ResourceManagement.getCultureFromUser(options, async function (culture) {
			var newTranslation = {
				Id: 0,
				AppId: app.Id,
				Culture: culture,
				Key: resource.Key,
				Name: resource.Name,
				DisplayName: resource.DisplayName,
				ShortDisplayName: resource.ShortDisplayName,
				Description: resource.Description
			};
			await api.add("ContentManagement/Resource", newTranslation).then((r) => {
				notification.success("[resource_displayname[translationcreated]]".replace("[culture]", r.Culture));
				model.prepareItem(r, typeInfo);
				translationsGrid.dataSource().add(r);
			}).catch((err) => error(err));
		});
	},

	getCultureFromUser: function (options, callback) {
		var culture = null;
		var d = new Dialog({
			width: 600,
			title: "[resource_displayname[newtranslation]]"
		});
		d.template = $("script[name=newTranslation]").html();
		d.events.confirm = function () {
			callback(culture.val());
			d.events.close();
		};
		d.init(() => {
			culture = $("select", d.element).kendoDropDownList({ dataTextField: "Name", dataValueField: "Id", dataSource: options, index: 0 });
		});
	},

	migrate: function (app) {
		var d = new Dialog({ width: 1100, height: 600, title: "[resource_displayname[migrate]]" });
		d.template = $("[name=resourceMigrationComponent]").first().html();
		d.init(() =>  ResourceMigration.init(app, $(".component[name=ResourceMigration]", d.element)));
	},


	newResource: async function (e, app, grid) {
		var newResource = { Id: 0, AppId: app.Id, Culture: "", Key: "", Name: "", DisplayName: "", ShortDisplayName: "", Description: "", };
		var args = {
			fields: [
				{ field: "Key", title: "[resource_displayname[key]]", description: "[resource_description[key]]" },
				{ field: "Name", title: "[resource_displayname[name]]", description: "[resource_description[name]]" },
				{ field: "DisplayName", title: "[resource_displayname[displayname]]", description: "[resource_description[displayname]]" },
				{ field: "ShortDisplayName", title: "[resource_displayname[shortdisplayname]]", description: "[resource_description[shortdisplayname]]" },
				{ field: "Description", title: "[resource_displayname[description]]", description: "[resource_description[description]]" }
			],
			title: "[resource_displayname[newresource]]",
			width: 510,
			resourceKey: "CMS",
			data: newResource,
			confirm: "[resource_displayname[confirm]]",
			close:"[resource_displayname[close]]"
		};
		var resourceDialog = new EditorDialog(args);
		resourceDialog.events.confirm = async function () {
			newResource = resourceDialog.data.toJSON();
			await api.add("ContentManagement/Resource", newResource).then(() => {
				resourceDialog.events.close();
				notification.success("[resource_displayname[created]]");
				grid.refresh();
			}).catch((err) => error(err));
		};
		await resourceDialog.init(args.data);
	},

	save: async function (e, grid) {
		e.preventDefault();
		var resource = grid.dataItem($(e.currentTarget).closest("tr"));
		await resource.save().then(notification.success("[resource_displayname[saved]]"));
		grid.refresh();
	},

	destroy: function (e, grid) {
		e.preventDefault();
		var resource = grid.dataItem($(e.currentTarget).closest("tr"));
		var d = new ConfirmDialog({ 
			title: "[resource_displayname[areyousure]]",
			question: "[resource_displayname[areyousure]]",
			confirm: "[resource_displayname[confirm]]",
			close: "[resource_displayname[close]]"
		});
		d.events.confirm = async function () {
			d.events.close();
			await api.destroy("ContentManagement/Resource(" + resource.Id + ")").then(async () => {
				notification.success("[resource_displayname[deleted]]");
				grid.refresh();
			}).catch((err) => error(err));
		};
		d.init();
	}
};",
