    }
		]);
		var config = {
			endpoint: "ContentManagement/Component",
			odataAppend: "?$filter=AppId eq " + app.Id,
			group: {
				field: "Key"
			},
			sort: [
				{
					field: "Key", dir: "asc"
				},
				{
					field: "Name", dir: "asc"
				}
			]
		};
		let ds = await model.getDatasource(config);
		var grid = new GridWidget(container, ds);
		grid.toolbar = [
			{ 
				template: `<button name='create'><span class='k-icon k-i-plus'></span>[resource_displayname[new]]</button>
					<button name='migrate'><span class='k-icon k-i-plus'></span>[resource_displayname[migrate]]</button>`
			 }
		];
		grid.search = {
			fields: ["Key", "ResourceKey", "Name", "LastUpdatedBy"]
		};
		grid.columns = [
			{
				field: "Key",
				title: "[resource_displayname[key]]"
			},
			{
				field: "ResourceKey",
				title: "[resource_displayname[resourcekey]]"
			},
			{
				field: "Name",
				title: "[resource_displayname[name]]"
			},
			{
				field: "LastUpdated",
				title: "[resource_displayname[lastupdated]]",
				type: "date",
				format: "{0: " + type.dateFormat + " hh:mm}"
			},
            {
				field: "LastUpdatedBy",
				title: "[resource_displayname[lastupdatedby]]"
			},
		];
		grid.commands.push({
			name: "save",
			icon: "k-i-save",
			text: "[resource_displayname[save]]"
		});
		grid.commands.push({
			name: "delete",
			icon: "k-i-delete",
			text: "[resource_displayname[delete]]"
		});
		grid.detailTemplate = kendo.template($("[name=componentDetails]", container).html()),
		grid.groupable = false;
		grid.searchable = true;
		grid.filterable = true;
		grid.detailExpand = function (e) {
			$(e.detailRow).find(".monaco-editor").css("visbility", "visible");
			if ($(e.detailRow).find(".monaco-editor").length === 0) {
				var component = this.dataItem(e.masterRow);
				var contentEditor = $(e.detailRow).find("div[name=content]", container.parent());
				var scriptEditor = $(e.detailRow).find("div[name=script]", container.parent());
				var html = new HTMLMonacoEditor(contentEditor[0], {
					code: component.Content
				});
				var script = new JavaScriptMonacoEditor(scriptEditor[0], {
					code: component.Script
				});
				html.onChange = (e) => {
					component.Content = html.getValue();
				}; 
				script.onChange = (e) => {
					component.Script = script.getValue();
				};
				html.init();
				script.init();
			}
		};
		grid.detailCollapse = function (e) {
			$(e.detailRow).find(".monaco-editor").css("visbility", "hidden");
		};
		grid.dataBound = function () {
			$("button[name=save]", grid.gridElement).on("click", (e) => ComponentManagement.save(e, grid));
			$("button[name=delete]", grid.gridElement).on("click", (e) => ComponentManagement.destroy(e, grid));
		};
		await grid.init();
		$("button[name=create]", grid.gridElement).on("click", (e) => ComponentManagement.newComponent(e, grid, app));
		$("button[name=migrate]", grid.gridElement).off("click").on("click", (e) => ComponentManagement.migrate(e, app));
	},

	migrate: function (e, app) {
		e.preventDefault();
		var d = new Dialog({
			width: 1100,
			height: 520,
			title: "[resource_displayname[migrateComponents]]"
		});
		d.template = $("[name=componentMigrationComponent]").first().html();
		d.init(() => ComponentMigration.init(app, $(".component[name=ComponentMigration]", d.element)));
	},

	newComponent: async function (e, grid, app) {
		e.preventDefault();
		var newComponent = {
			Id: 0,
			AppId: app.Id,
			Name: "",
			Key: "",
			ResourceKey: "",
			Content: "",
			Script: ""
		};
		var args = {
			fields: [
				{
					field: "Name",
					title: "[resource_displayname[name]]",
					description: "[resource_description[name]]"
				},
				{
					field: "Key",
					title: "[resource_displayname[key]]",
					description: "[resource_description[key]]"
				},
				{
					field: "ResourceKey",
					title: "[resource_displayname[resourcekey]]",
					description: "[resource_description[resourcekey]]"
				}
			],
			title: "[resource_displayname[CreateNewComponent]]",
			resourceKey: "CMS",
			data: newComponent,
			confirm: "[resource_displayname[confirm]]",
			close: "[resource_displayname[close]]"
		};
		var addComponentDialog = new EditorDialog(args);
		addComponentDialog.events.confirm = async function () {
			newComponent = addComponentDialog.data.toJSON();//Remove all the kendo observable properties.
			await api.add("ContentManagement/Component", newComponent).then(() => {
				addComponentDialog.events.close();
				notification.success("[resource_displayname[componentcreated]]");
				grid.refresh();
			}).catch((err) => error(err));
		};
		addComponentDialog.init();
	},

	delay: function (callback, ms) {
		var timer = 0;
		return function () {
			var context = this, args = arguments;
			clearTimeout(timer);
			timer = setTimeout(function () {
				callback.apply(context, args);
			}, ms || 0);
		};
	},

	save: async function (e, grid) {
		e.preventDefault();
		var component = grid.dataItem($(e.currentTarget).closest("tr"));
		await component.save(e);
		notification.success("Component Saved");
	},

	destroy: function (e, grid) {
		e.preventDefault();
		var d = new ConfirmDialog({
			title: "[resource_displayname[areyousure]]",
			question: "[resource_displayname[areyousure]]",
			confirm: "[resource_displayname[confirm]]",
			close: "[resource_displayname[close]]"
		});
		d.events.confirm = function () {
			var component = grid.dataItem($(e.currentTarget).closest("tr"));
			component.destroy(e);
			notification.success("[resource_displayname[deleted]]");
			grid.refresh();
			d.events.close();
		};
		d.init();
	}
};",
