    "Script": "CalendarManagement = {
    days: {
        0: "[resource_displayname[sunday]]",
        1: "[resource_displayname[monday]]",
        2: "[resource_displayname[tuesday]]",
        3: "[resource_displayname[wednesday]]",
        4: "[resource_displayname[thursday]]",
        5: "[resource_displayname[friday]]",
        6: "[resource_displayname[saturday]]"
    },
    months: {
        1: "[resource_displayname[month-1]]",
        2: "[resource_displayname[month-2]]",
        3: "[resource_displayname[month-3]]",
        4: "[resource_displayname[month-4]]",
        5: "[resource_displayname[month-5]]",
        6: "[resource_displayname[month-6]]",
        7: "[resource_displayname[month-7]]",
        8: "[resource_displayname[month-8]]",
        9: "[resource_displayname[month-9]]",
        10: "[resource_displayname[month-10]]",
        11: "[resource_displayname[month-11]]",
        12: "[resource_displayname[month-12]]"
    },

    repeats: {
        "never": "[resource_displayname[never]]",
        "weekly": "[resource_displayname[weekly]]"
    },
    
    init: async function (app, container, args) {
        app = app || session.app;
        container = container || $(".component[name=CalendarManagement]");

        if(args && args.fromDate && args.toDate) {
            if(args.toDate < args.fromDate) {
                let copy = new Date(toDate.getTime());
                args.toDate = args.fromDate;
                args.fromDate = copy;
            }
        }
        
        app = await api.get("ContentManagement/App(" + app.Id + ")");
        app.Config = JSON.parse(app.ConfigJson);
        var calendarData = await api.get("Workflow/Calendar?$filter=AppId eq " + app.Id);
        var currentMonth = new Date().getMonth() +1 ;
        var monthData = [];
        for (const [key, value] of Object.entries(CalendarManagement.months)) {
            monthData.push({ Name: value, Number: key });
        }
        var yearData = [];
        var currentYear = new Date().getFullYear();
        for (var i = currentYear - 10; i < currentYear + 10; i++){
            yearData.push(i);
        }

        var defaultArgs = () => ({
            calendarId: app.Config.Calendars.primary, 
            month: parseInt($("[name=month]", container).val()) - 1,
            year: parseInt($("[name=year]", container).val()), 
            readOnly: (args && args.readOnly) ? true : false,
            eventSource: (args && args.eventSource) ? args.eventSource : null,
            fromDate: (args && args.fromDate) ? args.fromDate : null, 
            toDate: (args && args.toDate) ? args.toDate : null,
            agendaView: (args && args.agendaView) ? true : false
        });

        $("[name=calendars]",container).kendoDropDownList({ dataTextField: "Name", dataValueField: "Id", dataSource: calendarData.value, change: async function(){
                await CalendarManagement.initCalendar(container, defaultArgs());
         } });
        var monthDropdown = $("[name=month]", container).kendoDropDownList({
            dataTextField: "Name", dataValueField: "Number", value: currentMonth, dataSource: monthData, change: async function () { 
                await CalendarManagement.initCalendar(container, defaultArgs());            
            }
        }).data("kendoDropDownList");
        var yearDropdown = $("[name=year]", container).kendoDropDownList({
            dataSource: yearData, value: currentYear, change: async function () {
                await CalendarManagement.initCalendar(container, defaultArgs());
            }
        }).data("kendoDropDownList");
        
        if(args && args.fromDate != null) {
            monthDropdown.value(args.fromDate.getMonth());
            yearDropdown.value(args.fromDate.getFullYear());
        }

        await CalendarManagement.initCalendar(container, defaultArgs());
        $("[name=newcalendar]", container).on("click", function(e) { CalendarManagement.newCalendar(e, app); });
        $("[name=setprimary]", container).on("click", (e) => CalendarManagement.setPrimary(e, app, container));
        $("[name=deletecalendar]", container).on("click", (e) => CalendarManagement.deleteCalendar(e, container));
        if(args && args.readOnly) { $("[name=toolbar]", container).remove(); }
    },

    setPrimary: async function(e, app, container) {
        e.preventDefault();
        var serverApp = await api.get("ContentManagement/App(" + app.Id + ")");
        var config = JSON.parse(serverApp.ConfigJson);
        config.Calendars.primary = $("[name=calendars]", container).val();
        serverApp.ConfigJson = JSON.stringify(config);
        await api.update("ContentManagement/App(" + serverApp.Id + ")", serverApp)
            .then(() => notification.success("[resource_displayname[saved]]"))
            .catch((err) => error(err));
    },

    deleteCalendar: async function(e, container) {
        e.preventDefault();
        var calendar = $("[name=calendars]", container).val();
        await api.destroy("Workflow/Calendar(" + calendar + ")")
            .catch((err) => error(err));

        window.location.reload();
    },

    initCalendar: async function (container, args) {

        var firstDay = args.fromDate ? args.fromDate : new Date(args.year, args.month, 1);
        var lastDay = args.toDate ? args.toDate : new Date(args.year, args.month + 1, 1);

        let calendarEvents = args.eventSource;
        if(!args.eventSource) {
            calendarEvents = (await api.get("Workflow/CalendarEvent?$filter=CalendarId eq " + args.calendarId + " and Start ge " + firstDay.toISOString().split("T")[0] + " and Start le " + lastDay.toISOString().split("T")[0])).value;
            calendarEvents.map(c => {
                c.Start = new Date(c.Start);
                c.End = new Date(c.Start + 1000 * 3600 * 24 * 1);
            });
        }
        console.log(calendarEvents);
        
        let calendarElements = [];
        let dateCopy = new Date(firstDay.getTime());
        while(dateCopy.getTime() <= lastDay.getTime()) {
            if(CalendarManagement.dateFallsInBetween(dateCopy, firstDay, lastDay)) {
                calendarElements.push({
                    Day: dateCopy.getDate(),
                    FriendlyName: 
                        (args && args.agendaView) 
                            ?  (dateCopy.getDate() + " " + CalendarManagement.days[dateCopy.getDay()] + " " + CalendarManagement.months[dateCopy.getMonth()])
                            : dateCopy.getDate() + " " + CalendarManagement.days[dateCopy.getDay()],
                    IsWeekend: dateCopy.getDay() == 6 || dateCopy.getDay() == 0,
                    Start: dateCopy.toISOString(),
                    Events: calendarEvents.filter(r => CalendarManagement.DatesEqualOnDay(r.Start, dateCopy))
                });
            }
            dateCopy.setDate(dateCopy.getDate() + 1);
        }

        if(args && args.agendaView) {
            calendarElements = calendarElements.filter(r => r.Events.length > 0);
        }

        var viewModel = kendo.observable({ calendarDays: calendarElements });
        console.log(viewModel);
        kendo.bind($("[name=calendarEvents]", container), viewModel);
        if(!args.readOnly) {
            $("[name=newEvent]", container).on("click", function (e) { CalendarManagement.newCalendarEvent(e, args.calendarId, $(this).attr("data-start"), container, args); });
            $("[name=deleteEvent]", container).on("click", function (e) { CalendarManagement.deleteCalendarEvent(e, $(this).attr("data-eventId"), container, args); });
        } else {
            $("[name=newEvent]", container).hide();
            $("[name=deleteEvent]", container).hide();
        }
    },

    dateFallsInBetween(current, fromDate, toDate) {
        if(fromDate && !toDate) { return current >= fromDate; }
        if(fromDate && toDate) { return current >= fromDate && current <= toDate; }
        if(!fromDate && toDate) { return current <= toDate; }
        return true;
    },

    newCalendar: async function(e, app){
        e.preventDefault();
		var calendar = {
			Id: 0,
			AppId: app.Id,
			Name: "",
		};
		var args = {
			fields: [
				{ field: "Name", title: "[resource_displayname[name]]", description: "[resource_description[name]]" }, 
			],
			title: "[resource_displayname[newcalendar]]",
			data: calendar,
			confirm: "[resource_displayname[confirm]]",
			close: "[resource_displayname[close]]"
		};
		var addCalendarDialog = new EditorDialog(args);
		addCalendarDialog.events.confirm = async function () {
			calendar = addCalendarDialog.data.toJSON();//Remove all the kendo observable properties.
			await api.add("Workflow/Calendar", calendar).then(async (calendarCreated)=>{
                addCalendarDialog.events.close();
                var currentApp = await api.get("ContentManagement/App(" + app.Id + ")");
                var config = JSON.parse(currentApp.ConfigJson);
                config.Calendars[calendarCreated.Name] = calendarCreated.Id;
                currentApp.ConfigJson = JSON.stringify(config);
                await api.put("ContentManagement/App(" + currentApp.Id + ")", currentApp).then(()=>{
                    notification.success("[resource_displayname[created]]");
                    window.location.reload();
                }).catch((err)=>error(err));
            }).catch((err)=>error(err));
		};
		addCalendarDialog.init();
	},

    newCalendarEvent: async function(e, calendarId, start, container, args) {
        e.preventDefault();
        var startInformation = new Date(start);
        var trueStart = new Date(Date.UTC(startInformation.getFullYear(), startInformation.getMonth(), startInformation.getDate()));
		var calendarEvent = kendo.observable({
			Id: 0,
            CalendarId: calendarId,
			Name: "",
            Start: trueStart.toISOString(),
            DurationInTicks: 1000000*24*60*60
		});
        var addCalendarEventDialog = new Dialog({title: "[resource_displayname[newevent]] for " + CalendarManagement.days[new Date(start).getDay()]});
        addCalendarEventDialog.template = $("[name=newCalendarEventDialog]").first().html();
        addCalendarEventDialog.events.confirm = async function() {
			calendarEvent = calendarEvent.toJSON();
            var repeatsEvery = $("[name=repeatsEvery]", addCalendarEventDialog.element).val();
            var until = $("[name=until]", addCalendarEventDialog.element).val();
            if(repeatsEvery == "never") {
                await api.add("Workflow/CalendarEvent", calendarEvent).then(async ()=>{
                    addCalendarEventDialog.events.close();
                    notification.success("[resource_displayname[created]]");
                    await CalendarManagement.initCalendar(container, args);
                }).catch((err) => error(err));    
            } else if(repeatsEvery == "weekly") {
                var start = new Date(trueStart);
                var untilDate = $("[name=until]", addCalendarEventDialog.element).data("kendoDateTimePicker").value();
                var events = [];
                while(start < untilDate) {
                    events.push({
                        Id: calendarEvent.Id,
                        CalendarId: calendarEvent.CalendarId,
                        Name: calendarEvent.Name,
                        Start: start.toISOString(),
                        DurationInTicks: calendarEvent.DurationInTicks
                    });
                    start.setDate(start.getDate() + 7);
                }
                notification.info("[resource_displayname[adding]]");
                await api.post("Workflow/CalendarEvent/AddAll", { value: events }).then(async ()=>{
                    addCalendarEventDialog.events.close();
                    notification.success("[resource_displayname[created]]");
                    await CalendarManagement.initCalendar(container, args);
                }).catch((err) => error(err));    
            }
			
        };
        addCalendarEventDialog.init(() => {
            kendo.bind(addCalendarEventDialog.element, calendarEvent);
            $("[name=repeatsEvery]", addCalendarEventDialog.element).kendoDropDownList({
                dataSource: Object.keys(CalendarManagement.repeats).map(r => ({ Text: CalendarManagement.repeats[r], Value: r })),
                dataTextField: "Text",
                dataValueField: "Value"
            });
            $("[name=until]", addCalendarEventDialog.element).kendoDateTimePicker({ autoBind: false, value: new Date(), dateInput: true, format: type.dateFormat });
        });
	},

    deleteCalendarEvent: async function(e, eventId, container, args){
        e.preventDefault();
        await api.destroy("Workflow/CalendarEvent(" + eventId + ")").then(async () =>{
            notification.success("[resource_displayname[deleted]]");
            await CalendarManagement.initCalendar(container, args);
        }).catch((err)=>error(err));
    },

    DatesEqualOnDay(date1, date2) {
        var date1Hack = new Date(date1.getFullYear(), date1.getMonth(), date1.getDate());
        var date2Hack = new Date(date2.getFullYear(), date2.getMonth(), date2.getDate());
        return date1Hack.toISOString().split("T")[0] == date2Hack.toISOString().split("T")[0];
    }
